package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class ThousandChangeTest {
 @Test public void every18002ArbitraryStartChecksPublicPromptAndThreeBlankFrames(){int count=0;for(String id:List.of(ThousandChange.MORE,ThousandChange.LESS))for(int i=0;i<=9000;i++){int start=i+(id.equals(ThousandChange.LESS)?1000:0),expected=start+(id.equals(ThousandChange.MORE)?1000:-1000);Question q=ThousandChange.make(id,start);q.answers=new String[]{"99999"};q.expression="99999";assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(expected+1))).status);HelpPlan p=HelpPlan.forQuestion(q);assertEquals(3,p.size());assertFalse(p.canTransfer());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] entries={start,1000,expected};for(int step=0;step<3;step++)assertTrue(p.step(step).accepts(""+entries[step]));count++;}assertEquals(18002,count);}
 @Test public void actualYearFourFreshSupplyAndFullHistoryOldest(){for(String id:List.of(ThousandChange.MORE,ThousandChange.LESS)){Generator g=new Generator(new Random(141));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",id,4);List<String> recent=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,limits);assertTrue(seen.add(q.signature()));assertNotNull(ThousandChange.read(q));recent.add(q.signature());}Map<String,Integer> full=new LinkedHashMap<>();for(int i=0;i<=9000;i++)full.put(ThousandChange.make(id,i+(id.equals(ThousandChange.LESS)?1000:0)).signature(),i);assertEquals(full.keySet().iterator().next(),ThousandChange.next(id,new Random(1),limits,full).signature());}}
 @Test public void badDirectionsRangesAndUnknownPromptsIgnoreStoredKeys(){for(String id:List.of(ThousandChange.MORE,ThousandChange.LESS))for(String prompt:List.of("unknown",String.format(ThousandChange.template(id),-1),String.format(ThousandChange.template(id),10001),String.format(ThousandChange.template(id),id.equals(ThousandChange.MORE)?9001:999),String.format(ThousandChange.template(id.equals(ThousandChange.MORE)?ThousandChange.LESS:ThousandChange.MORE),2345))){Question q=new Question(id,prompt,"0","0");assertNull(ThousandChange.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}}
}
